     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.report.Report;
     4	import br.com.marealta.report.ReportCatalog;
     5	import br.com.marealta.report.ReportRenderer;
     6	import br.com.marealta.service.ApiException;
     7	import br.com.marealta.service.ReservationService;
     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	import com.fasterxml.jackson.databind.SerializationFeature;
    10	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
    11	import io.javalin.Javalin;
    12	import io.javalin.http.Context;
    13	import io.javalin.json.JavalinJackson;
    14	import java.util.Map;
    15	
    16	/** HTTP routes. */
    17	public final class Api {
    18	
    19	    private final ReservationService service;
    20	    private final ReportCatalog reports;
    21	    private final ObjectMapper mapper = new ObjectMapper()
    22	            .registerModule(new JavaTimeModule())
    23	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    24	
    25	    public Api(ReservationService service, ReportCatalog reports) {
    26	        this.service = service;
    27	        this.reports = reports;
    28	    }
    29	
    30	    public Javalin create() {
    31	        Javalin app = Javalin.create(cfg -> {
    32	            cfg.jsonMapper(new JavalinJackson(mapper, false));
    33	            cfg.showJavalinBanner = false;
    34	        });
    35	
    36	        app.get("/rooms", ctx -> ctx.json(service.listRooms()));
    37	        app.post("/reservations", ctx -> ctx.status(201).json(service.create(
    38	                RequestParser.parseBooking(mapper, ctx.body()))));
    39	        app.get("/reservations/{id}", ctx -> ctx.json(service.get(id(ctx))));
    40	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(service.confirm(id(ctx))));
    41	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(service.cancel(id(ctx))));
    42	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(service.checkIn(id(ctx))));
    43	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(service.checkOut(id(ctx))));
    44	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(id(ctx))));
    45	        app.get("/messages", ctx -> ctx.json(service.listMessages()));
    46	
    47	        for (Report report : reports.all()) {
    48	            app.get("/reports/" + report.name(), ctx -> {
    49	                String csv = reports.csv(report, ctx.queryParam(report.periodKind().parameter()));
    50	                ctx.contentType(ReportRenderer.CONTENT_TYPE).result(csv);
    51	            });
    52	        }
    53	
    54	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    55	        app.exception(Exception.class, (e, ctx) -> {
    56	            e.printStackTrace();
    57	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    58	        });
    59	        return app;
    60	    }
    61	
    62	    private static String id(Context ctx) {
    63	        return ctx.pathParam("id");
    64	    }
    65	
    66	    private static void error(Context ctx, int status, String code, String message) {
    67	        ctx.status(status).json(Map.of("error", code, "message", message));
    68	    }
    69	}
=== src/main/java/br/com/marealta/web/RequestParser.java
     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.RatePlan;
     4	import br.com.marealta.service.ApiException;
     5	import br.com.marealta.service.BookingRequest;
     6	import com.fasterxml.jackson.databind.JsonNode;
     7	import com.fasterxml.jackson.databind.ObjectMapper;
     8	import java.time.LocalDate;
     9	import java.time.format.DateTimeParseException;
    10	import java.util.regex.Pattern;
    11	
    12	/** Validates the POST /reservations body. */
    13	final class RequestParser {
    14	
    15	    private static final Pattern ISO_DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
    16	
    17	    private RequestParser() {}
    18	
    19	    static BookingRequest parseBooking(ObjectMapper mapper, String body) {
    20	        JsonNode json;
    21	        try {
    22	            json = mapper.readTree(body);
    23	        } catch (Exception e) {
    24	            throw ApiException.invalid("O corpo não é um JSON válido");
    25	        }
    26	        if (json == null || !json.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON");
    27	
    28	        JsonNode room = json.get("roomNumber");
    29	        if (room == null || !room.isIntegralNumber() || !room.canConvertToInt()) {
    30	            throw ApiException.invalid("Campo 'roomNumber' ausente ou inválido");
    31	        }
    32	        JsonNode guests = json.get("guests");
    33	        if (guests == null || !guests.isIntegralNumber() || !guests.canConvertToInt()) {
    34	            throw ApiException.invalid("Campo 'guests' ausente ou inválido");
    35	        }
    36	        String name = text(json, "guestName");
    37	        String email = text(json, "guestEmail");
    38	        String cpf = text(json, "guestCpf");
    39	        LocalDate checkIn = date(json, "checkIn");
    40	        LocalDate checkOut = date(json, "checkOut");
    41	        RatePlan plan;
    42	        try {
    43	            plan = RatePlan.valueOf(text(json, "ratePlan"));
    44	        } catch (IllegalArgumentException e) {
    45	            throw ApiException.invalid("Campo 'ratePlan' inválido");
    46	        }
    47	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("A saída deve ser depois da entrada");
    48	        if (guests.intValue() < 1) throw ApiException.invalid("É preciso ao menos um hóspede");
    49	        return new BookingRequest(room.intValue(), name, email, cpf, checkIn, checkOut, guests.intValue(), plan);
    50	    }
    51	
    52	    private static String text(JsonNode json, String field) {
    53	        JsonNode n = json.get(field);
    54	        if (n == null || !n.isTextual() || n.textValue().isBlank()) {
    55	            throw ApiException.invalid("Campo '" + field + "' ausente ou inválido");
    56	        }
    57	        return n.textValue();
    58	    }
    59	
    60	    private static LocalDate date(JsonNode json, String field) {
    61	        String value = text(json, field);
    62	        try {
    63	            if (!ISO_DATE.matcher(value).matches()) throw new DateTimeParseException("format", value, 0);
    64	            return LocalDate.parse(value);
    65	        } catch (DateTimeParseException e) {
    66	            throw ApiException.invalid("Campo '" + field + "' deve estar no formato AAAA-MM-DD");
    67	        }
    68	    }
    69	}
