     3	public class ApiException extends RuntimeException {
     4	    private final int status;
     5	    private final String code;
     6	
     7	    public ApiException(int status, String code, String message) {
     8	        super(message);
     9	        this.status = status;
    10	        this.code = code;
    11	    }
    12	
    13	    public int status() { return status; }
    14	
    15	    public String code() { return code; }
    16	
    17	    public static ApiException invalid(String message) {
    18	        return new ApiException(400, "INVALID_REQUEST", message);
    19	    }
    20	
    21	    public static ApiException roomNotFound(int number) {
    22	        return new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + number + " não existe");
    23	    }
    24	
    25	    public static ApiException reservationNotFound(String id) {
    26	        return new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe");
    27	    }
    28	
    29	    public static ApiException roomUnavailable() {
    30	        return new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    31	    }
    32	
    33	    public static ApiException notAllowed(String message) {
    34	        return new ApiException(409, "OPERATION_NOT_ALLOWED", message);
    35	    }
    36	
    37	    public static ApiException capacityExceeded(int capacity) {
    38	        return new ApiException(422, "CAPACITY_EXCEEDED", "O quarto comporta no máximo " + capacity + " hóspedes");
    39	    }
    40	}
