     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.RatePlan;
     4	import br.com.marealta.service.ApiException;
     5	import br.com.marealta.service.BookingRequest;
     6	import com.fasterxml.jackson.databind.JsonNode;
     7	import com.fasterxml.jackson.databind.ObjectMapper;
     8	import java.time.LocalDate;
     9	import java.time.format.DateTimeParseException;
    10	import java.util.regex.Pattern;
    11	
    12	/** Validates the POST /reservations body. */
    13	final class RequestParser {
    14	
    15	    private static final Pattern ISO_DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
    16	
    17	    private RequestParser() {}
    18	
    19	    static BookingRequest parseBooking(ObjectMapper mapper, String body) {
    20	        JsonNode json;
    21	        try {
    22	            json = mapper.readTree(body);
    23	        } catch (Exception e) {
    24	            throw ApiException.invalid("O corpo não é um JSON válido");
    25	        }
    26	        if (json == null || !json.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON");
    27	
    28	        JsonNode room = json.get("roomNumber");
    29	        if (room == null || !room.isIntegralNumber() || !room.canConvertToInt()) {
    30	            throw ApiException.invalid("Campo 'roomNumber' ausente ou inválido");
    31	        }
    32	        JsonNode guests = json.get("guests");
    33	        if (guests == null || !guests.isIntegralNumber() || !guests.canConvertToInt()) {
    34	            throw ApiException.invalid("Campo 'guests' ausente ou inválido");
    35	        }
    36	        String name = text(json, "guestName");
    37	        String email = text(json, "guestEmail");
    38	        String cpf = text(json, "guestCpf");
    39	        LocalDate checkIn = date(json, "checkIn");
    40	        LocalDate checkOut = date(json, "checkOut");
    41	        RatePlan plan;
    42	        try {
    43	            plan = RatePlan.valueOf(text(json, "ratePlan"));
    44	        } catch (IllegalArgumentException e) {
    45	            throw ApiException.invalid("Campo 'ratePlan' inválido");
    46	        }
    47	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("A saída deve ser depois da entrada");
    48	        if (guests.intValue() < 1) throw ApiException.invalid("É preciso ao menos um hóspede");
    49	        return new BookingRequest(room.intValue(), name, email, cpf, checkIn, checkOut, guests.intValue(), plan);
    50	    }
    51	
    52	    private static String text(JsonNode json, String field) {
    53	        JsonNode n = json.get(field);
    54	        if (n == null || !n.isTextual() || n.textValue().isBlank()) {
    55	            throw ApiException.invalid("Campo '" + field + "' ausente ou inválido");
    56	        }
    57	        return n.textValue();
    58	    }
    59	
    60	    private static LocalDate date(JsonNode json, String field) {
    61	        String value = text(json, field);
    62	        try {
    63	            if (!ISO_DATE.matcher(value).matches()) throw new DateTimeParseException("format", value, 0);
    64	            return LocalDate.parse(value);
    65	        } catch (DateTimeParseException e) {
    66	            throw ApiException.invalid("Campo '" + field + "' deve estar no formato AAAA-MM-DD");
    67	        }
    68	    }
    69	}
