     1	package br.com.marealta.service;
     2	
     3	import br.com.marealta.db.Database;
     4	import br.com.marealta.db.MessageRepository;
     5	import br.com.marealta.db.ReservationRepository;
     6	import br.com.marealta.db.RoomRepository;
     7	import br.com.marealta.domain.Channel;
     8	import br.com.marealta.domain.Message;
     9	import br.com.marealta.domain.Money;
    10	import br.com.marealta.domain.Quote;
    11	import br.com.marealta.domain.Receipt;
    12	import br.com.marealta.domain.Reservation;
    13	import br.com.marealta.domain.ReservationStatus;
    14	import br.com.marealta.domain.Room;
    15	import java.sql.Connection;
    16	import java.sql.SQLException;
    17	import java.util.List;
    18	
    19	public final class ReservationService {
    20	
    21	    public static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    22	
    23	    private final Database db;
    24	    private final RoomRepository rooms;
    25	    private final ReservationRepository reservations;
    26	    private final MessageRepository messages;
    27	
    28	    public ReservationService(Database db, RoomRepository rooms, ReservationRepository reservations,
    29	                              MessageRepository messages) {
    30	        this.db = db;
    31	        this.rooms = rooms;
    32	        this.reservations = reservations;
    33	        this.messages = messages;
    34	    }
    35	
    36	    public List<Room> listRooms() {
    37	        return db.transaction(rooms::findAll);
    38	    }
    39	
    40	    public List<Message> listMessages() {
    41	        return db.transaction(messages::findAll);
    42	    }
    43	
    44	    public Reservation create(BookingRequest req) {
    45	        return db.transaction(c -> {
    46	            Room room = rooms.find(c, req.roomNumber()).orElseThrow(() -> ApiException.roomNotFound(req.roomNumber()));
    47	            if (req.guests() > room.capacity()) throw ApiException.capacityExceeded(room.capacity());
    48	            rooms.lock(c, room.number());
    49	            if (reservations.hasOverlap(c, room.number(), req.checkIn(), req.checkOut())) {
    50	                throw ApiException.roomUnavailable();
    51	            }
    52	            Quote quote = Quote.of(room, req.checkIn(), req.checkOut(), req.ratePlan());
    53	            Reservation draft = new Reservation(0, room.number(), req.guestName(), req.guestEmail(), req.guestCpf(),
    54	                    req.checkIn(), req.checkOut(), req.guests(), req.ratePlan(), quote.nights(), quote.subtotal(),
    55	                    quote.discount(), quote.total(), ReservationStatus.PENDING, Money.ZERO, null);
    56	            return reservations.insert(c, draft);
    57	        });
    58	    }
    59	
    60	    public Reservation get(String id) {
    61	        return db.transaction(c -> load(c, id, false));
    62	    }
    63	
    64	    public Reservation confirm(String id) {
    65	        return db.transaction(c -> {
    66	            Reservation r = load(c, id, true);
    67	            require(r, r.status() == ReservationStatus.PENDING, "Só é possível confirmar uma reserva pendente");
    68	            Reservation confirmed = r.confirmed();
    69	            reservations.updateState(c, confirmed);
    70	            Room room = rooms.find(c, r.roomNumber()).orElseThrow();
    71	            messages.add(c, Channel.EMAIL, r.guestEmail(), CONFIRMATION_SUBJECT, confirmationBody(r, room));
    72	            return confirmed;
    73	        });
    74	    }
    75	
    76	    public Reservation cancel(String id) {
    77	        return transition(id, r -> r.status() == ReservationStatus.PENDING || r.status() == ReservationStatus.CONFIRMED,
    78	                "Só é possível cancelar uma reserva pendente ou confirmada antes do check-in", Reservation::cancelled);
    79	    }
    80	
    81	    public Reservation checkIn(String id) {
    82	        return transition(id, r -> r.status() == ReservationStatus.CONFIRMED,
    83	                "Só é possível fazer check-in de uma reserva confirmada", r -> r.withStatus(ReservationStatus.CHECKED_IN));
    84	    }
    85	
    86	    public Receipt checkOut(String id) {
    87	        return db.transaction(c -> {
    88	            Reservation r = load(c, id, true);
    89	            require(r, r.status() == ReservationStatus.CHECKED_IN, "Só é possível fazer check-out após o check-in");
    90	            Reservation done = r.withStatus(ReservationStatus.CHECKED_OUT);
    91	            reservations.updateState(c, done);
    92	            return Receipt.of(done, rooms.find(c, r.roomNumber()).orElseThrow());
    93	        });
    94	    }
    95	
    96	    /** Second copy of the receipt; only exists for paid reservations. */
    97	    public Receipt document(String id) {
    98	        return db.transaction(c -> {
    99	            Reservation r = load(c, id, false);
   100	            require(r, r.isPaid(), "Só existe comprovante para reserva paga");
   101	            return Receipt.of(r, rooms.find(c, r.roomNumber()).orElseThrow());
   102	        });
   103	    }
   104	
   105	    private interface Rule {
   106	        boolean allows(Reservation r);
   107	    }
   108	
   109	    private Reservation transition(String id, Rule rule, String refusal,
   110	                                   java.util.function.UnaryOperator<Reservation> change) {
   111	        return db.transaction(c -> {
   112	            Reservation r = load(c, id, true);
   113	            require(r, rule.allows(r), refusal);
   114	            Reservation next = change.apply(r);
   115	            reservations.updateState(c, next);
   116	            return next;
   117	        });
   118	    }
   119	
   120	    private static void require(Reservation r, boolean ok, String message) {
   121	        if (!ok) throw ApiException.notAllowed(message + " (situação atual: " + r.status() + ")");
   122	    }
   123	
   124	    private Reservation load(Connection c, String id, boolean forUpdate) throws SQLException {
   125	        long parsed;
   126	        try {
   127	            parsed = Long.parseLong(id);
   128	        } catch (NumberFormatException e) {
   129	            throw ApiException.reservationNotFound(id);
   130	        }
   131	        return reservations.find(c, parsed, forUpdate).orElseThrow(() -> ApiException.reservationNotFound(id));
   132	    }
   133	
   134	    static String confirmationBody(Reservation r, Room room) {
   135	        return "Olá, " + r.guestName() + "!\n\n"
   136	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
   137	                + Receipt.of(r, room).text() + "\n\n"
   138	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   139	                + "Até breve!";
   140	    }
   141	}

