     1	package br.com.marealta.db;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	import java.sql.Connection;
     6	import java.sql.SQLException;
     7	import java.sql.Statement;
     8	
     9	/** Connection pool, schema creation and transaction helper. */
    10	public final class Database implements AutoCloseable {
    11	
    12	    @FunctionalInterface
    13	    public interface Work<T> {
    14	        T run(Connection connection) throws SQLException;
    15	    }
    16	
    17	    private static final String SCHEMA = """
    18	            CREATE TABLE IF NOT EXISTS rooms (
    19	                number       INTEGER PRIMARY KEY,
    20	                type         VARCHAR(20) NOT NULL,
    21	                capacity     INTEGER NOT NULL,
    22	                nightly_rate NUMERIC(12,2) NOT NULL
    23	            );
    24	            CREATE TABLE IF NOT EXISTS reservations (
    25	                id          BIGSERIAL PRIMARY KEY,
    26	                room_number INTEGER NOT NULL REFERENCES rooms(number),
    27	                guest_name  TEXT NOT NULL,
    28	                guest_email TEXT NOT NULL,
    29	                guest_cpf   TEXT NOT NULL,
    30	                check_in    DATE NOT NULL,
    31	                check_out   DATE NOT NULL,
    32	                guests      INTEGER NOT NULL,
    33	                rate_plan   VARCHAR(20) NOT NULL,
    34	                nights      INTEGER NOT NULL,
    35	                subtotal    NUMERIC(12,2) NOT NULL,
    36	                discount    NUMERIC(12,2) NOT NULL,
    37	                total       NUMERIC(12,2) NOT NULL,
    38	                status      VARCHAR(20) NOT NULL,
    39	                amount_paid NUMERIC(12,2) NOT NULL DEFAULT 0,
    40	                refund      NUMERIC(12,2)
    41	            );
    42	            CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in);
    43	            CREATE INDEX IF NOT EXISTS reservations_check_in_idx ON reservations (check_in);
    44	            CREATE TABLE IF NOT EXISTS messages (
    45	                id      BIGSERIAL PRIMARY KEY,
    46	                channel VARCHAR(20) NOT NULL,
    47	                to_addr TEXT NOT NULL,
    48	                subject TEXT NOT NULL,
    49	                body    TEXT NOT NULL
    50	            );
    51	            INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    52	                (101, 'STANDARD', 2, 249.90),
    53	                (102, 'STANDARD', 2, 249.90),
    54	                (201, 'DELUXE',   3, 389.90),
    55	                (202, 'DELUXE',   3, 389.90),
    56	                (301, 'SUITE',    4, 579.90)
    57	            ON CONFLICT (number) DO NOTHING;
    58	            """;
    59	
    60	    private final HikariDataSource pool;
    61	
    62	    public Database(String url, String user, String password) {
    63	        HikariConfig cfg = new HikariConfig();
    64	        cfg.setJdbcUrl(url);
    65	        if (user != null) cfg.setUsername(user);
    66	        if (password != null) cfg.setPassword(password);
    67	        cfg.setMaximumPoolSize(10);
    68	        cfg.setInitializationFailTimeout(-1); // the database may still be starting up
    69	        this.pool = new HikariDataSource(cfg);
    70	    }
    71	
    72	    /** Creates what the system needs, waiting for the database to accept connections. */
    73	    public void migrate() {
    74	        long deadline = System.currentTimeMillis() + 60_000;
    75	        while (true) {
    76	            try {
    77	                transaction(c -> {
    78	                    try (Statement st = c.createStatement()) {
    79	                        // serializes concurrent starts of several instances
    80	                        st.execute("SELECT pg_advisory_xact_lock(727274)");
    81	                        st.execute(SCHEMA);
    82	                    }
    83	                    return null;
    84	                });
    85	                return;
    86	            } catch (RuntimeException e) {
    87	                if (System.currentTimeMillis() > deadline) throw e;
    88	                try {
    89	                    Thread.sleep(1000);
    90	                } catch (InterruptedException ie) {
    91	                    Thread.currentThread().interrupt();
    92	                    throw e;
    93	                }
    94	            }
    95	        }
    96	    }
    97	
    98	    public <T> T transaction(Work<T> work) {
    99	        try (Connection c = pool.getConnection()) {
   100	            c.setAutoCommit(false);
   101	            try {
   102	                T result = work.run(c);
   103	                c.commit();
   104	                return result;
   105	            } catch (Throwable t) {
   106	                c.rollback();
   107	                throw t;
   108	            }
   109	        } catch (SQLException e) {
   110	            throw new IllegalStateException("Database error: " + e.getMessage(), e);
   111	        }
   112	    }
   113	
   114	    @Override
   115	    public void close() {
   116	        pool.close();
   117	    }
   118	}
