     1	package br.com.marealta.db;
     2	
     3	import br.com.marealta.domain.RatePlan;
     4	import br.com.marealta.domain.Reservation;
     5	import br.com.marealta.domain.ReservationStatus;
     6	import java.sql.Connection;
     7	import java.sql.Date;
     8	import java.sql.PreparedStatement;
     9	import java.sql.ResultSet;
    10	import java.sql.SQLException;
    11	import java.sql.Statement;
    12	import java.time.LocalDate;
    13	import java.util.ArrayList;
    14	import java.util.List;
    15	import java.util.Optional;
    16	
    17	public final class ReservationRepository {
    18	
    19	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    20	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    21	
    22	    /** Inserts the reservation and returns it with its generated id. */
    23	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    24	        String sql = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    25	                + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
    26	                + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
    27	        try (PreparedStatement ps = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    28	            ps.setInt(1, r.roomNumber());
    29	            ps.setString(2, r.guestName());
    30	            ps.setString(3, r.guestEmail());
    31	            ps.setString(4, r.guestCpf());
    32	            ps.setDate(5, Date.valueOf(r.checkIn()));
    33	            ps.setDate(6, Date.valueOf(r.checkOut()));
    34	            ps.setInt(7, r.guests());
    35	            ps.setString(8, r.ratePlan().name());
    36	            ps.setInt(9, r.nights());
    37	            ps.setBigDecimal(10, r.subtotal());
    38	            ps.setBigDecimal(11, r.discount());
    39	            ps.setBigDecimal(12, r.total());
    40	            ps.setString(13, r.status().name());
    41	            ps.setBigDecimal(14, r.amountPaid());
    42	            ps.setBigDecimal(15, r.refund());
    43	            ps.executeUpdate();
    44	            try (ResultSet keys = ps.getGeneratedKeys()) {
    45	                keys.next();
    46	                return new Reservation(keys.getLong("id"), r.roomNumber(), r.guestName(), r.guestEmail(),
    47	                        r.guestCpf(), r.checkIn(), r.checkOut(), r.guests(), r.ratePlan(), r.nights(), r.subtotal(),
    48	                        r.discount(), r.total(), r.status(), r.amountPaid(), r.refund());
    49	            }
    50	        }
    51	    }
    52	
    53	    public void updateState(Connection c, Reservation r) throws SQLException {
    54	        try (PreparedStatement ps = c.prepareStatement(
    55	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    56	            ps.setString(1, r.status().name());
    57	            ps.setBigDecimal(2, r.amountPaid());
    58	            ps.setBigDecimal(3, r.refund());
    59	            ps.setLong(4, r.id());
    60	            ps.executeUpdate();
    61	        }
    62	    }
    63	
    64	    public Optional<Reservation> find(Connection c, long id, boolean forUpdate) throws SQLException {
    65	        String sql = "SELECT " + COLUMNS + " FROM reservations WHERE id = ?" + (forUpdate ? " FOR UPDATE" : "");
    66	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    67	            ps.setLong(1, id);
    68	            try (ResultSet rs = ps.executeQuery()) {
    69	                return rs.next() ? Optional.of(map(rs)) : Optional.empty();
    70	            }
    71	        }
    72	    }
    73	
    74	    /** True if a non-cancelled reservation of the room overlaps any night of [checkIn, checkOut). */
    75	    public boolean hasOverlap(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
    76	        try (PreparedStatement ps = c.prepareStatement(
    77	                "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
