     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	/** Price of a stay: sum of the nights, discount and total. */
     7	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     8	
     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    10	
    11	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    12	        BigDecimal subtotal = Money.ZERO;
    13	        int nights = 0;
    14	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    15	            subtotal = subtotal.add(nightPrice(room, night));
    16	            nights++;
    17	        }
    18	        BigDecimal discount = Money.round(subtotal.multiply(plan.discountRate()));
    19	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
    20	    }
    21	
    22	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    23	        BigDecimal rate = room.nightlyRate();
    24	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : Money.round(rate);
    25	    }
    26	
    27	    /** High season: 15 Dec to the end of February, and all of July. */
    28	    public static boolean isHighSeason(LocalDate night) {
    29	        int month = night.getMonthValue();
    30	        return month == 1 || month == 2 || month == 7 || (month == 12 && night.getDayOfMonth() >= 15);
    31	    }
    32	}
