     9	
    10	/** Shared selections of reservations starting in a month. */
    11	final class MonthlyReservations {
    12	
    13	    private MonthlyReservations() {}
    14	
    15	    /** Reservations starting in the month, by check-in date then id. */
    16	    static List<Reservation> starting(ReservationRepository repo, Connection c, String month) throws SQLException {
    17	        YearMonth ym = PeriodKind.month(month);
    18	        return repo.findCheckInBetween(c, ym.atDay(1), ym.plusMonths(1).atDay(1));
    19	    }
    20	
    21	    /** Reservations starting in the month that left money with the inn (paid minus refunded). */
    22	    static List<Reservation> withRevenue(ReservationRepository repo, Connection c, String month) throws SQLException {
    23	        return starting(repo, c, month).stream().filter(r -> r.amountKept().signum() > 0).toList();
    24	    }
    25	}
