     1	package br.com.marealta.report;
     2	
     3	import br.com.marealta.service.ApiException;
     4	import java.time.LocalDate;
     5	import java.time.YearMonth;
     6	import java.util.regex.Pattern;
     7	
     8	/** What period a report covers, and how it is given in the query string. */
     9	public enum PeriodKind {
    10	    DATE("date", "\\d{4}-\\d{2}-\\d{2}"),
    11	    MONTH("month", "\\d{4}-\\d{2}");
    12	
    13	    private final String parameter;
    14	    private final Pattern format;
    15	
    16	    PeriodKind(String parameter, String format) {
    17	        this.parameter = parameter;
    18	        this.format = Pattern.compile(format);
    19	    }
    20	
    21	    public String parameter() { return parameter; }
    22	
    23	    /** Checks the raw query value and returns it in canonical form (2027-07-10 or 2027-07). */
    24	    public String normalize(String raw) {
    25	        if (raw == null || !format.matcher(raw).matches()) {
    26	            throw ApiException.invalid("Parâmetro '" + parameter + "' ausente ou em formato inválido");
    27	        }
    28	        try {
    29	            return this == DATE ? LocalDate.parse(raw).toString() : YearMonth.parse(raw).toString();
    30	        } catch (java.time.DateTimeException e) {
    31	            throw ApiException.invalid("Parâmetro '" + parameter + "' inválido: " + raw);
    32	        }
    33	    }
    34	
    35	    public static LocalDate date(String period) { return LocalDate.parse(period); }
    36	
    37	    public static YearMonth month(String period) { return YearMonth.parse(period); }
    38	}
