     9	/** All available reports, and the single path from "report name + period" to CSV text. */
    10	public final class ReportCatalog {
    11	
    12	    private final Database db;
    13	    private final Map<String, Report> reports = new LinkedHashMap<>();
    14	
    15	    public ReportCatalog(Database db, List<Report> reports) {
    16	        this.db = db;
    17	        reports.forEach(r -> this.reports.put(r.name(), r));
    18	    }
    19	
    20	    public List<Report> all() {
    21	        return List.copyOf(reports.values());
    22	    }
    23	
    24	    /** Generates the CSV of a report; {@code rawPeriod} is the query value as received. */
    25	    public String csv(Report report, String rawPeriod) {
    26	        String period = report.periodKind().normalize(rawPeriod);
    27	        ReportTable table = db.transaction(c -> report.build(c, period));
    28	        return ReportRenderer.render(table);
    29	    }
    30	
    31	    public Report get(String name) {
    32	        Report r = reports.get(name);
    33	        if (r == null) throw new ApiException(404, "REPORT_NOT_FOUND", "Relatório " + name + " não existe");
