104	
105	/** End-to-end test against the PostgreSQL given in DB_URL; uses a throw-away schema. */
106	@EnabledIfEnvironmentVariable(named = "DB_URL", matches = ".+")
107	class ApiTest {
108	
109	    private static final ObjectMapper JSON = new ObjectMapper();
110	    private static final HttpClient HTTP = HttpClient.newHttpClient();
111	    private static String schema;
112	    private static String baseDb;
113	    private static Javalin app;
114	    private static String base;
115	
116	    @BeforeAll
117	    static void start() throws Exception {
118	        baseDb = System.getenv("DB_URL");
119	        schema = "t_" + UUID.randomUUID().toString().replace("-", "");
120	        try (Connection c = connect(baseDb); Statement st = c.createStatement()) {
121	            st.execute("CREATE SCHEMA " + schema);
122	        }
123	        String url = baseDb + (baseDb.contains("?") ? "&" : "?") + "currentSchema=" + schema;
124	        app = App.start(new Config(0, url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"), Config.DEFAULT_TOURISM_TAX));
125	        base = "http://localhost:" + app.port();
126	    }
127	
128	    @AfterAll
129	    static void stop() throws Exception {
130	        if (app != null) app.stop();
131	        try (Connection c = connect(baseDb); Statement st = c.createStatement()) {
132	            st.execute("DROP SCHEMA " + schema + " CASCADE");
133	        }
134	    }
135	
136	    private static Connection connect(String url) throws Exception {
137	        return DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
138	    }
139	
140	    private record Res(int status, String body, String contentType) {
141	        JsonNode json() throws Exception { return JSON.readTree(body); }
142	    }
143	
144	    private static Res call(String method, String path, String body) throws Exception {
145	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
146	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
147	        HttpResponse<String> r = HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
148	        return new Res(r.statusCode(), r.body(), r.headers().firstValue("content-type").orElse(""));
149	    }
150	
151	    private static String booking(int room, String in, String out, int guests, String plan) {
152	        return """
153	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@example.com","guestCpf":"111.222.333-44",
154	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, in, out, guests, plan);
155	    }
156	
157	    @Test
158	    void fullFlow() throws Exception {
159	        Res rooms = call("GET", "/rooms", null);
160	        assertEquals(5, rooms.json().size());
161	        assertEquals(389.90, rooms.json().get(2).get("nightlyRate").asDouble());
162	
163	        Res created = call("POST", "/reservations", booking(201, "2027-03-10", "2027-03-12", 2, "STANDARD"));
164	        assertEquals(201, created.status());
165	        long id = created.json().get("id").asLong();
166	        assertEquals("PENDING", created.json().get("status").asText());
167	        assertTrue(created.body().contains("\"total\":779.80"), created.body());
168	        assertTrue(created.json().get("refund").isNull());
169	
170	        assertEquals(409, call("POST", "/reservations", booking(201, "2027-03-11", "2027-03-13", 2, "STANDARD")).status());
171	        assertEquals(422, call("POST", "/reservations", booking(101, "2027-03-11", "2027-03-13", 3, "STANDARD")).status());
172	        assertEquals(400, call("POST", "/reservations", booking(101, "2027-03-13", "2027-03-13", 1, "STANDARD")).status());
173	        assertEquals(404, call("POST", "/reservations", booking(999, "2027-03-11", "2027-03-13", 1, "STANDARD")).status());
174	        assertEquals(400, call("POST", "/reservations", "nope").status());
175	
176	        assertEquals(409, call("GET", "/reservations/" + id + "/document", null).status());
177	        assertEquals(409, call("POST", "/reservations/" + id + "/check-in", null).status());
178	        Res confirmed = call("POST", "/reservations/" + id + "/confirmation", null);
179	        assertEquals("CONFIRMED", confirmed.json().get("status").asText());
180	        assertTrue(confirmed.body().contains("\"amountPaid\":779.80"));
181	        assertEquals(409, call("POST", "/reservations/" + id + "/confirmation", null).status());
182	
183	        JsonNode msgs = call("GET", "/messages", null).json();
184	        assertEquals(1, msgs.size());
185	        assertEquals("Reserva confirmada - Pousada Maré Alta", msgs.get(0).get("subject").asText());
186	        assertEquals("EMAIL", msgs.get(0).get("channel").asText());
187	        assertTrue(msgs.get(0).get("body").asText().startsWith("Olá, Carla Dias!\n\nSua reserva"));
188	
189	        Res occ = call("GET", "/reports/occupancy?date=2027-03-10", null);
190	        assertEquals("text/csv; charset=utf-8", occ.contentType.toLowerCase().replace("charset=utf-8", "charset=utf-8"));
191	        assertEquals("Pousada Maré Alta,occupancy,2027-03-10\nroom,type,reservation,check_in,check_out\n"
192	                + "201,DELUXE," + id + ",2027-03-10,2027-03-12\ntotal,1/5\n", occ.body());
193	        assertTrue(call("GET", "/reports/occupancy?date=2027-03-12", null).body().endsWith("total,0/5\n"));
194	
195	        Res tax = call("GET", "/reports/tourism-tax?month=2027-03", null);
196	        assertTrue(tax.body().contains(",2,2,18.00\n"), tax.body());
197	        assertTrue(tax.body().endsWith("total,18.00\n"));
198	        assertEquals(400, call("GET", "/reports/revenue?month=2027-13", null).status());
199	        assertEquals(400, call("GET", "/reports/revenue", null).status());
200	
201	        assertEquals("CHECKED_IN", call("POST", "/reservations/" + id + "/check-in", null).json().get("status").asText());
202	        assertEquals(409, call("POST", "/reservations/" + id + "/cancellation", null).status());
203	        Res out = call("POST", "/reservations/" + id + "/check-out", null);
204	        assertEquals("Comprovante de reserva", out.json().get("title").asText());
205	        assertEquals("DELUXE", out.json().get("roomType").asText());
206	        assertEquals(out.json(), call("GET", "/reservations/" + id + "/document", null).json());
207	    }
208	
209	    @Test
210	    void cancellationsAndPlanReport() throws Exception {
211	        long nr = call("POST", "/reservations", booking(301, "2027-08-01", "2027-08-03", 2, "NON_REFUNDABLE")).json().get("id").asLong();
212	        call("POST", "/reservations/" + nr + "/confirmation", null);
213	        Res cancelled = call("POST", "/reservations/" + nr + "/cancellation", null);
214	        assertEquals("CANCELLED", cancelled.json().get("status").asText());
215	        assertEquals(0.0, cancelled.json().get("refund").asDouble());
216	        // room is free again, and the pending cancellation leaves nothing
217	        long again = call("POST", "/reservations", booking(301, "2027-08-01", "2027-08-03", 2, "STANDARD")).json().get("id").asLong();
218	        Res c2 = call("POST", "/reservations/" + again + "/cancellation", null);
219	        assertEquals(0.0, c2.json().get("refund").asDouble());
220	        long std = call("POST", "/reservations", booking(301, "2027-08-05", "2027-08-06", 2, "STANDARD")).json().get("id").asLong();
221	        call("POST", "/reservations/" + std + "/confirmation", null);
222	        Res c3 = call("POST", "/reservations/" + std + "/cancellation", null);
223	        assertEquals(579.90, c3.json().get("refund").asDouble());
224	
225	        Res plans = call("GET", "/reports/rate-plans?month=2027-08", null);
226	        assertEquals("Pousada Maré Alta,rate-plans,2027-08\nrate_plan,reservations,amount\nSTANDARD,0,0.00\n"
227	                + "NON_REFUNDABLE,1,985.83\ntotal,1,985.83\n", plans.body());
228	        Res rev = call("GET", "/reports/revenue?month=2027-08", null);
229	        assertTrue(rev.body().contains(",CANCELLED,985.83\n"), rev.body());
230	        assertEquals(404, call("GET", "/reservations/abc", null).status());
231	    }
232	}

