144	    private static Res call(String method, String path, String body) throws Exception {
145	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
146	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
147	        HttpResponse<String> r = HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
148	        return new Res(r.statusCode(), r.body(), r.headers().firstValue("content-type").orElse(""));
149	    }
